export function applyPageImprovements(pages) {
  for (const update of updates) {
    const page = pages.find((p) => p.locales[update.locale]?.path === update.path)?.locales[update.locale];
    if (!page) throw new Error(`Missing content target: ${update.path}`);
    let index = -1;
    const replace = update.replaceHeading || update.replaceHtmlContaining || update.replaceFirstRichtext;
    if (update.replaceHeading) index = page.blocks.findIndex((b) => b.heading === update.replaceHeading);
    else if (update.replaceHtmlContaining) index = page.blocks.findIndex((b) => b.html?.includes(update.replaceHtmlContaining));
    else if (update.replaceFirstRichtext) index = page.blocks.findIndex((b) => b.type === "richtext");
    else if (update.beforeHeading) index = page.blocks.findIndex((b) => b.heading === update.beforeHeading);
    else index = page.blocks.findIndex((b) => b.type === "faq" || b.type === "finalCta");
    if (index < 0) throw new Error(`Missing section target: ${update.path}`);
    const block = { ...update.block, surface: replace ? Boolean(page.blocks[index].surface) : false };
    if (replace && page.blocks[index].id) block.id = page.blocks[index].id;
    page.blocks.splice(index, replace ? 1 : 0, block);
  }
  return pages;
}
